-- IMPORT CALCULATOR: load calculations from the owner's CSV exports as saved files with all their lines.
-- Each one is added only once (same customer + landed total). The saved date is taken from the archive when the totals match there.
-- Safe to re-run. Run on the MAIN Supabase project only.

INSERT INTO public.import_calculations (customer_name, reference, config, lines, total_landed, total_sell, total_profit, created_at, updated_at)
SELECT 'Nwa Far', 'Anchor Bolt',
  '{"buyCurrency": "CNY", "localCurrency": "LKR", "exchangeRate": 207.0, "seafreight": 0.0, "totalImportCost": 3800000.0, "importTaxPercent": null, "boostedSettings": null, "allocMode": "kg"}'::jsonb,
  '[{"id": "2be22930-2382-4054-9cea-1609c5ba4953", "code": "M12*100", "buyPrice": 0.41, "dutyRate": null, "unit": "Pcs", "qty": 15000.0, "weight": 0.087, "totalWeight": null, "cubic": null, "marginPercent": null, "marketPrice": null, "sellPrice": 190.0}, {"id": "0c006179-e17f-462f-9054-13aeb3402ddf", "code": "M16*100", "buyPrice": 0.8, "dutyRate": null, "unit": "Pcs", "qty": 15000.0, "weight": 0.162, "totalWeight": null, "cubic": null, "marginPercent": null, "marketPrice": null, "sellPrice": 380.0}, {"id": "8de0740d-5b60-4808-ae7d-23444283be19", "code": "M16*150", "buyPrice": 1.1, "dutyRate": null, "unit": "Pcs", "qty": 15000.0, "weight": 0.226, "totalWeight": null, "cubic": null, "marginPercent": null, "marketPrice": null, "sellPrice": 500.0}]'::jsonb,
  10972550.0, 16050000.0, 5077450.0,
  coalesce((SELECT min(created_at) FROM public.import_calculations_archive WHERE round(total_landed, 0) = round(10972550.0::numeric, 0)), now()), now()
WHERE NOT EXISTS (SELECT 1 FROM public.import_calculations WHERE customer_name = 'Nwa Far' AND round(total_landed, 0) = round(10972550.0::numeric, 0));

